/**
 * Korean - MU's original language.
 *
 * Class, event and item-option names are the ones the Korean client uses.
 * Tahoma has no Hangul, so `font` puts a Korean face in front of it.
 */

import type { LanguageLayer } from './layer';

export const koreanLayer: LanguageLayer = {
  name: 'korean',
  code: 'ko',
  aliases: ['ko-KR'],
  label: '한국어',
  region: 'KR',
  font: '"Malgun Gothic", "Apple SD Gothic Neo", "Noto Sans KR"',
  // Generated by `tools/localPacks.ts`: items, monsters, warps.
  dataPack: { folder: 'Kor', suffix: 'kor', encoding: 'utf-8' },
};
